.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d21;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #333;
}

.sidebar-header {
    padding: 16px;
    margin: 0;
    font-size: 1.1rem;
    color: #fff;
    border-bottom: 1px solid #333;
}

.channel-list {
    list-style: none;
    padding: 0;
    margin: 0;
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 10px 16px;
    cursor: pointer;
    border-left: 3px solid transparent;
    position: relative;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #27292d;
}

.channel-item.active {
    background: #1164a3;
    border-left-color: #fff;
    color: #fff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.95rem;
}

.channel-description {
    font-size: 0.75rem;
    color: #999;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.channel-item.active .channel-description {
    color: #cde;
}

.unread-badge {
    position: absolute;
    top: 10px;
    right: 12px;
    background: #e01e5a;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    border-radius: 10px;
    padding: 2px 7px;
    min-width: 18px;
    text-align: center;
}

/* Main Message Area */
.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #fff;
    min-width: 0;
}

.message-area.thread-open {
    max-width: 55%;
}

.message-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
    background: #fafafa;
}

.message-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #1d1c1d;
}

.message-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #616061;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #888;
    font-size: 0.85rem;
}

.message-item {
    padding: 8px 12px;
    border-radius: 6px;
    position: relative;
    margin-bottom: 4px;
