    padding: 4px 6px;
    border-radius: 4px;
}

.emoji-btn:hover {
    background: #f0f0f0;
}

/* Message Input */
.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #e0e0e0;
    background: #fafafa;
    align-items: flex-end;
}

.message-input-area textarea {
    flex: 1;
