    flex-direction: column;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    background: #fafafa;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-btn {
    border: none;
    background: transparent;
    font-size: 1.5rem;
    cursor: pointer;
    color: #666;
    line-height: 1;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #f0f0f0;
    color: #333;
}

.thread-root-message {
    padding: 12px 16px;
    background: #f8f8fa;
    border-bottom: 1px solid #e8e8e8;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.thread-panel .message-input-area {
    padding: 12px 16px;
}

